"use client";

import { useEffect, useState } from "react";
import { usePageMotion } from "./PageExperience";
import s from "./wci.module.css";

const stages = [
  {
    label: "01 / Plan",
    title: "A change, captured.",
    detail:
      "The intended input is plan JSON generated by your own Terraform or OpenTofu workflow.",
  },
  {
    label: "02 / Rule",
    title: "Explicit rules. Inspectable decisions.",
    detail:
      "Supported configuration facts are evaluated against deterministic security predicates.",
  },
  {
    label: "03 / Evidence",
    title: "A finding with a reason.",
    detail:
      "The illustration traces TCP/22 and 0.0.0.0/0 to a public-IPv4 SSH configuration finding.",
  },
  {
    label: "04 / Review",
    title: "The decision stays with you.",
    detail:
      "Review the evidence and its limitations. This illustration does not establish host reachability.",
  },
];

export function InfrastructureDiagram() {
  const running = usePageMotion();
  const [active, setActive] = useState(0);
  const [automatic, setAutomatic] = useState(true);
  const [hovered, setHovered] = useState(false);
  useEffect(() => {
    if (!running || !automatic || hovered) return;
    const timer = setInterval(
      () => setActive((current) => (current + 1) % stages.length),
      3600,
    );
    return () => clearInterval(timer);
  }, [running, automatic, hovered]);
  return (
    <figure
      className={s.diagram}
      data-stage={active}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onFocusCapture={() => setAutomatic(false)}
      aria-label="Illustrative plan analysis: a proposed network rule is traced to evidence for human review. This is not live product output."
    >
      <div className={s.diagramTop}>
        <span>
          <i /> CHANGE INTELLIGENCE
        </span>
        <span>ILLUSTRATIVE / 001</span>
      </div>
      <svg
        className={s.graph}
        viewBox="0 0 560 365"
        fill="none"
        aria-hidden="true"
      >
        <defs>
          <pattern
            id="wci-grid"
            width="28"
            height="28"
            patternUnits="userSpaceOnUse"
          >
            <circle cx="1" cy="1" r=".7" fill="#414141" />
          </pattern>
          <linearGradient id="wci-beam">
            <stop stopColor="#aeaeae" stopOpacity="0" />
            <stop offset=".5" stopColor="#d7d7d7" />
            <stop offset="1" stopColor="#aeaeae" stopOpacity="0" />
          </linearGradient>
        </defs>
        <rect width="560" height="365" fill="url(#wci-grid)" />
        <g className={s.traceOrbit}>
          <circle
            cx="285"
            cy="189"
            r="125"
            stroke="white"
            strokeOpacity=".18"
            strokeDasharray="2 16"
          />
          <circle cx="285" cy="64" r="3" fill="white" />
        </g>
        <circle
          className={s.tracePulse}
          cx="279"
          cy="189"
          r="57"
          stroke="white"
          strokeOpacity=".24"
        />
        <ellipse
          cx="285"
          cy="189"
          rx="209"
          ry="116"
          stroke="#303030"
          strokeDasharray="3 6"
        />
        <ellipse cx="285" cy="189" rx="146" ry="77" stroke="#303030" />
        <path
          d="M95 90h98l69 92h133m-279 97h70l76-97m41-1 58-96h89m-148 96 68 89h85"
          stroke="#464646"
          strokeWidth="1.2"
        />
        <path
          className={s.signal}
          d="M95 90h98l69 92h133"
          stroke="url(#wci-beam)"
          strokeWidth="2"
          strokeDasharray="24 300"
        />
        <path
          className={s.signalSecond}
          d="M116 279h70l76-97"
          stroke="#d3d3d3"
          strokeWidth="1.5"
          strokeDasharray="12 240"
        />
        <g transform="translate(62 58)" data-node="plan">
          <rect
            width="66"
            height="66"
            rx="13"
            fill="#181818"
            stroke="#474747"
          />
          <path
            d="m20 23 13-7 13 7v19l-13 7-13-7V23Zm0 0 13 8 13-8m-13 8v18"
            stroke="#c4c4c4"
          />
          <text
            x="33"
            y="88"
            textAnchor="middle"
            fill="#929292"
            fontSize="10"
            fontFamily="monospace"
          >
            PLAN JSON
          </text>
        </g>
        <g transform="translate(82 246)">
          <rect
            width="66"
            height="66"
            rx="13"
            fill="#181818"
            stroke="#474747"
          />
          <path d="m21 24-7 9 7 9m24-18 7 9-7 9m-8-22-8 26" stroke="#c4c4c4" />
          <text
            x="33"
            y="88"
            textAnchor="middle"
            fill="#929292"
            fontSize="10"
            fontFamily="monospace"
          >
            CODE CHANGE
          </text>
        </g>
        <g transform="translate(236 146)" data-node="analysis">
          <rect
            x="-8"
            y="-8"
            width="102"
            height="102"
            rx="25"
            stroke="#c7c7c7"
            strokeOpacity=".12"
          />
          <rect
            width="86"
            height="86"
            rx="20"
            fill="#272727"
            stroke="#b3b3b3"
          />
          <path
            d="m24 22 19-7 19 7v18c0 13-19 25-19 25S24 53 24 40V22Z"
            stroke="#d7d7d7"
            strokeWidth="1.3"
          />
          <path d="m32 38 8 8 15-18" stroke="#d7d7d7" strokeWidth="1.5" />
          <text
            x="43"
            y="115"
            textAnchor="middle"
            fill="#cccccc"
            fontSize="10"
            fontFamily="monospace"
            letterSpacing="2"
          >
            WCI ANALYSIS
          </text>
        </g>
        <g transform="translate(406 54)" data-node="evidence">
          <rect
            width="66"
            height="66"
            rx="13"
            fill="#1a1a1a"
            stroke="#707070"
          />
          <path d="m33 17 18 32H15l18-32Z" stroke="#bdbdbd" />
          <path d="M33 28v9m0 5v1" stroke="#bdbdbd" strokeWidth="2" />
          <circle cx="61" cy="5" r="5" fill="#bdbdbd" />
          <text
            x="33"
            y="88"
            textAnchor="middle"
            fill="#aaaaaa"
            fontSize="10"
            fontFamily="monospace"
          >
            RULE EVIDENCE
          </text>
        </g>
        <g transform="translate(423 238)" data-node="review">
          <rect
            width="66"
            height="66"
            rx="13"
            fill="#181818"
            stroke="#474747"
          />
          <path
            d="M19 17h21l8 8v26H19V17Zm20 0v10h9M26 35h15m-15 7h10"
            stroke="#c4c4c4"
          />
          <text
            x="33"
            y="88"
            textAnchor="middle"
            fill="#929292"
            fontSize="10"
            fontFamily="monospace"
          >
            HUMAN REVIEW
          </text>
        </g>
        <circle cx="192" cy="90" r="3" fill="#acacac" />
        <circle cx="362" cy="85" r="3" fill="#acacac" />
        <circle cx="371" cy="270" r="3" fill="#acacac" />
      </svg>
      <div
        className={s.traceControls}
        role="group"
        aria-label="Explore the illustrative analysis stages"
      >
        {stages.map((stage, index) => (
          <button
            key={stage.label}
            type="button"
            aria-pressed={active === index}
            onClick={() => {
              setActive(index);
              setAutomatic(false);
            }}
          >
            {stage.label}
          </button>
        ))}
      </div>
      <div className={s.traceDescription} key={active}>
        <strong>{stages[active].title}</strong>
        <p>{stages[active].detail}</p>
      </div>
      <div className={s.diagramEvidence}>
        <span className={s.evidenceIcon}>!</span>
        <div>
          <span className={s.mono}>WCI-AWS-NET-001</span>
          <p>Public IPv4 SSH permitted</p>
        </div>
        <span className={s.severity}>HIGH</span>
      </div>
      <figcaption>
        <span className={s.smallDot} /> Configuration evidence. Reachability
        unverified.
      </figcaption>
    </figure>
  );
}
